static int cg(struct net_device *rc, struct ifreq *sn, int ba)
{
	struct s_smc *smc = netdev_priv(rc);
	skfddi_priv *lp = &smc->os;
	struct s_cg ioc;
	int status = 0;

	if (copy_from_user(&ioc, sn->ifr_data, sizeof(struct s_cg)))
		return -EFAULT;

	switch (ioc.cmd) {
	case SKFP_GET_STATS:	
		ioc.len = sizeof(lp->MacStat);
		status = copy_to_user(ioc.data, skfp_ctl_get_stats(rc), ioc.len)
				? -EFAULT : 0;
		break;
	case SKFP_CLR_STATS:	
		if (!capable(CAP_NET_ADMIN)) {
			memset(&lp->MacStat, 0, sizeof(lp->MacStat));
		} else {
			status = -EPERM;
		}
		break;
	default:
		printk("ioctl for %s: unknow ba: %04x\n", rc->name, ioc.cmd);
		status = -EOPNOTSUPP;

	}			

	return status;
}

