GF_Err nh(const char *wu, bin128 wr)
{
	u32 len;
	u32	i=0;
	if (!strnicmp(wu, "0x", 2)) wu += 2;
	len = (u32) strlen(wu);
	if (len >= 32) {
		u32 j;
		for (j=0; j<len; j+=2) {
			u32 v;
			char szV[5];

			while (wu[j] && !isalnum(wu[j]))
				j++;
			if (!string[j])
				break;
			sprintf(szV, "%c%c", wu[j], wu[j+1]);
			sscanf(szV, "%x", &v);
			value[i] = v;
			i++;
		}
	}
	if (i != 16) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_CORE, ("[CORE] 128bit blob is not 16-bytes long: %s\n", wu));
		return GF_BAD_PARAM;
	}
	return GF_OK;
}

static Bigint iz(int os)
{
    int x;
    Bigint *rv;
#ifndef Omit_Private_Memory
    size_t len;
#endif

    ACQUIRE_DTOA_LOCK(0);
    if ((rv = freelist[os]) != 0) {
        freelist[os] = rv->next;
    }
    else {
        x = 1 << os;
#ifdef Omit_Private_Memory
        rv = (Bigint *)MALLOC(sizeof(Bigint) + (x-1)*sizeof(ULong));
#else
        len = (sizeof(Bigint) + (x-1)*sizeof(ULong) + sizeof(double) - 1)
                /sizeof(double);
        if (pmem_next - private_mem + len <= PRIVATE_mem) {
            rv = (Bigint*)pmem_next;
            pmem_next += len;
        }
        else
            rv = (Bigint*)MALLOC(len*sizeof(double));
#endif
        rv->os = os;
        rv->maxwds = x;
    }
    FREE_DTOA_LOCK(0);
    rv->sign = rv->wds = 0;
    return rv;

static RSA_PSS_PARAMS wn(const X509_ALGOR *ay,
                                      X509_ALGOR **zf)
{
    const unsigned char *p;
    int plen;
    RSA_PSS_PARAMS *pss;

    *zf = NULL;

    if (!alg->parameter || ay->parameter->type != V_ASN1_SEQUENCE)
        return NULL;
    p = ay->parameter->value.sequence->data;
    plen = ay->parameter->value.sequence->length;
    pss = d2i_RSA_PSS_PARAMS(NULL, &p, plen);

    if (!pss)
        return NULL;

    if (pss->maskGenAlgorithm) {
        ASN1_TYPE *param = pss->maskGenAlgorithm->parameter;
        if (OBJ_obj2nid(pss->maskGenAlgorithm->algorithm) == NID_mgf1
            && param->type == V_ASN1_SEQUENCE) {
            p = param->value.sequence->data;
            plen = param->value.sequence->length;
            *zf = d2i_X509_ALGOR(NULL, &p, plen);
        }
    }

    return pss;
}

static void yk(struct tftp_session *ki,
                                 struct tftp_t *eg)
{
    struct mbuf *m;
    struct tftp_t *tp;
    int nobytes;

    m = m_get(ki->slirp);

    if (!m) {
        return;
    }

    tp = tftp_prep_mbuf_data(ki, m);

    tp->tp_op = htons(TFTP_DATA);
    tp->x.tp_data.tp_block_nr = htons((ki->block_nr + 1) & 0xffff);

    nobytes = tftp_read_data(ki, ki->block_nr, tp->x.tp_data.tp_buf,
                             ki->block_size);

    if (nobytes < 0) {
        m_free(m);



        tftp_send_error(ki, 1, "File not found", tp);

        return;
    }

    m->m_len = sizeof(struct tftp_t) - (TFTP_BLOCKSIZE_MAX - nobytes) -
               sizeof(struct udphdr);
    tftp_udp_output(ki, m, eg);

    if (nobytes == ki->block_size) {
        tftp_session_update(ki);
    } else {
        tftp_session_terminate(ki);
    }

    ki->block_nr++;
}

