    return &pair->list;
}

static int rj(jas_iccattrval_t *xo, jas_stream_t *rd,
  int mc)
{
	jas_icccurv_t *curv = &xo->data.curv;
	unsigned int i;

	curv->numents = 0;
	curv->ents = 0;

	if (jas_iccgetuint32(rd, &curv->numents))
		goto error;
	if (!(curv->ents = jas_malloc(curv->numents * sizeof(jas_iccuint16_t))))
		goto error;
	for (i = 0; i < curv->numents; ++i) {
		if (jas_iccgetuint16(rd, &curv->ents[i]))
			goto error;
	}

	if (JAS_CAST(int, 4 + 2 * curv->numents) != mc)
		goto error;
	return 0;

error:
	jas_icccurv_destroy(xo);
	return -1;
}

