TPMI_SH_AUTH_SESSION_Unmarshal(TPMI_SH_AUTH_SESSION *xr, BYTE **ri, INT32 *xs, BOOL ns)
{
    TPM_RC rc = TPM_RC_SUCCESS;

    if (rc == TPM_RC_SUCCESS) {
	rc = TPM_HANDLE_Unmarshal(xr, ri, xs);  
    }
    if (rc == TPM_RC_SUCCESS) {
	BOOL isNotHmacSession = (*xr < HMAC_SESSION_FIRST ) || (*xr > HMAC_SESSION_LAST);
	BOOL isNotPolicySession = (*xr < POLICY_SESSION_FIRST) || (*xr > POLICY_SESSION_LAST);
	BOOL isNotLegalPwd = (*xr != TPM_RS_PW) || !allowPwd;
	if (isNotHmacSession &&
	    isNotPolicySession &&
	    isNotLegalPwd) {
	    rc = TPM_RC_VALUE;
	}
    }
    return rc;
}

