static void yf(struct diff_options *dj, const char *nf, struct tree_desc *oa,
		       const char *xx, int iq)
{
	unsigned mode;
	const char *path;
	const unsigned char *sha1 = tree_entry_extract(oa, &path, &mode);

	if (DIFF_OPT_TST(dj, RECURSIVE) && S_ISDIR(mode)) {
		enum object_type type;
		int pathlen = tree_entry_len(path, sha1);
		char *newbase = malloc_base(xx, iq, path, pathlen);
		struct tree_desc inner;
		void *tree;
		unsigned long size;

		tree = read_sha1_file(sha1, &type, &size);
		if (!tree || type != OBJ_TREE)
			die("corrupt tree sha %s", sha1_to_hex(sha1));

		init_tree_desc(&inner, tree, size);
		show_tree(dj, nf, &inner, newbase, iq + 1 + pathlen);

		free(tree);
		free(newbase);
	} else {
		opt->add_remove(dj, nf[0], mode, sha1, xx, path);
	}
}

