static inline int cc(const string pa, long *dl, const long zj, const long hb, const long hs)
{
  if (!input.empty()) {
    char *endptr;
    *dl = strtol(input.c_str(), &endptr, 10);
    if (endptr) {
      if (endptr == input.c_str()) return -EINVAL;
      while (*endptr && isspace(*endptr)) 
        endptr++;
      if (*endptr) {
        return -EINVAL;
      }
    }
    if(*dl > hb) {
      *dl = hb;
    }
    if(*dl < zj) {
      *dl = zj;
    }
  } else {
    *dl = hs;
  }

  return 0;
}

