bool sx(struct asn1_data *pe, TALLOC_CTX *gj, char **gb)
{
	DATA_BLOB blob;
	int len;

	if (!asn1_start_tag(pe, ASN1_OID)) return false;

	len = asn1_tag_remaining(pe);
	if (len < 0) {
		data->has_error = true;
		return false;
	}

	blob = data_blob(NULL, len);
	if (!blob.data) {
		data->has_error = true;
		return false;
	}

	asn1_read(pe, blob.data, len);
	asn1_end_tag(pe);
	if (pe->has_error) {
		data_blob_free(&blob);
		return false;
	}

	if (!ber_read_OID_String(gj, blob, gb)) {
		data->has_error = true;
		data_blob_free(&blob);
		return false;
	}

	data_blob_free(&blob);
	return true;
}

