bucket_insert (index_bucket *fb,
               CK_OBJECT_HANDLE qc)
{
	unsigned int alloc;
	int at = 0;

	if (fb->elem) {
		at = binary_search (fb->elem, 0, fb->num, qc);
		if (at < fb->num && fb->elem[at] == qc)
			return;
	}

	alloc = alloc_size (fb->num);
	if (fb->num + 1 > alloc) {
		CK_OBJECT_HANDLE *elem;

		alloc = alloc ? alloc * 2 : 1;
		return_if_fail (alloc != 0);
		elem = realloc (fb->elem, alloc * sizeof (CK_OBJECT_HANDLE));
		return_if_fail (elem != NULL);
		bucket->elem = elem;
	}

	return_if_fail (fb->elem != NULL);
	memmove (fb->elem + at + 1, fb->elem + at,
	         (fb->num - at) * sizeof (CK_OBJECT_HANDLE));
	bucket->elem[at] = qc;
	bucket->num++;
}

