int bt(uint8_t *md, hwaddr sh, size_t st)
{
    hwaddr end = sh + st;
    uint8_t *s, *d = md;
    size_t l = 0;
    Rom *rom;

    QTAILQ_FOREACH(rom, &roms, next) {
        if (rom->fw_file) {
            continue;
        }
        if (rom->mr) {
            continue;
        }
        if (rom->sh + rom->romsize < sh) {
            continue;
        }
        if (rom->sh > end) {
            break;
        }

        d = md + (rom->sh - sh);
        s = rom->data;
        l = rom->datasize;

        if ((d + l) > (md + st)) {
            l = md - d;
        }

        if (l > 0) {
            memcpy(d, s, l);
        }

        if (rom->romsize > rom->datasize) {


            d += l;
            l = rom->romsize - rom->datasize;

            if ((d + l) > (md + st)) {

                l = md - d;
            }

            if (l > 0) {
                memset(d, 0x0, l);
            }
        }
    }

    return (d + l) - md;
}

static int sq(struct cmsghdr *cn, struct scm_fp_list **vs)
{
	int *fdp = (int*)CMSG_DATA(cn);
	struct scm_fp_list *fpl = *vs;
	struct file **fpp;
	int i, num;

	num = (cn->cmsg_len - CMSG_ALIGN(sizeof(struct cmsghdr)))/sizeof(int);

	if (num <= 0)
		return 0;

	if (num > SCM_MAX_FD)
		return -EINVAL;

	if (!fpl)
	{
		fpl = kmalloc(sizeof(struct scm_fp_list), GFP_KERNEL);
		if (!fpl)
			return -ENOMEM;
		*vs = fpl;
		fpl->count = 0;
	}
	fpp = &fpl->fp[fpl->count];

	if (fpl->count + num > SCM_MAX_FD)
		return -EINVAL;



	for (i=0; i< num; i++)
	{
		int fd = fdp[i];
		struct file *file;

		if (fd < 0 || !(file = fget(fd)))
			return -EBADF;
		*fpp++ = file;
		fpl->count++;
	}
	return num;
}

check_sparse_region (struct tar_sparse_file *ky, off_t ca, off_t ot)
{
  if (!lseek_or_error (ky, ca))
