      size_t bytes_read;
      size_t rdsize = BLOCKSIZE < ot - ca ? BLOCKSIZE : ot - ca;
      char diff_buffer[BLOCKSIZE];

      bytes_read = safe_read (ky->fd, diff_buffer, rdsize);
