void tz(bitfile *or, int wj)
{
    uint32_t tmp;
    int words = wj >> 5;
    int remainder = wj & 0x1F;

    or->bytes_left = or->buffer_size - words*4;

    if (or->bytes_left >= 4)
    {
        tmp = getdword(&or->start[words]);
        or->bytes_left -= 4;
    } else {
        tmp = getdword_n(&or->start[words], or->bytes_left);
        or->bytes_left = 0;
    }
    or->bufa = tmp;

    if (or->bytes_left >= 4)
    {
        tmp = getdword(&or->start[words+1]);
        or->bytes_left -= 4;
    } else {
        tmp = getdword_n(&or->start[words+1], or->bytes_left);
        or->bytes_left = 0;
    }
    or->bufb = tmp;

    or->bits_left = 32 - remainder;
    or->tail = &or->start[words+2];


    or->error = 0;




}

