qb_log_blackbox_write_to_file(const char *un)
{
	ssize_t written_size = 0;
	struct qb_log_target *t;
	struct _blackbox_file_header header;
	int fd = open(un, O_CREAT | O_RDWR | O_EXCL, 0700);

	if (fd < 0) {
		return -errno;
	}


	header.word_size = QB_BLACKBOX_HEADER_WORDSIZE;
	header.read_pt   = QB_BLACKBOX_HEADER_READPT;
	header.write_pt  = QB_BLACKBOX_HEADER_WRITEPT;
	header.version   = QB_BLACKBOX_HEADER_VERSION;
	header.hash      = QB_BLACKBOX_HEADER_HASH;
	written_size = write(fd, &header, sizeof(header));
	if (written_size < sizeof(header)) {
		close(fd);
		return written_size;
	}

	t = qb_log_target_get(QB_LOG_BLACKBOX);
	if (t->instance) {
		written_size += qb_rb_write_to_file(t->instance, fd);
	} else {
		written_size = -ENOENT;
	}
	close(fd);

	return written_size;
}

static void fx(
    char const* ak,
    PointerHolder<char>& ye, size_t& ui)
{
    FILE* f = QUtil::safe_fopen(ak, "rb");
    fseek(f, 0, SEEK_END);
    ui = QUtil::tell(f);
    fseek(f, 0, SEEK_SET);
    ye = PointerHolder<char>(true, new char[ui]);
    char* buf_p = file_buf.getPointer();
    size_t bytes_read = 0;
    size_t len = 0;
    while ((len = fread(buf_p + bytes_read, 1, ui - bytes_read, f)) > 0)
    {
        bytes_read += len;
    }
    if (bytes_read != ui)
    {
        if (ferror(f))
        {
            throw std::runtime_error(
                std::string("failure reading file ") + ak +
                " into memory: read " +
                QUtil::uint_to_string(bytes_read) + "; wanted " +
                QUtil::uint_to_string(ui));
        }
        else
        {
            throw std::logic_error(
                std::string("premature eof reading file ") + ak +
                " into memory: read " +
                QUtil::uint_to_string(bytes_read) + "; wanted " +
                QUtil::uint_to_string(ui));
        }
    }
    fclose(f);
}

