TPM2B_ECC_POINT_Unmarshal(TPM2B_ECC_POINT *mb, BYTE **ph, INT32 *go)
{
    TPM_RC rc = TPM_RC_SUCCESS;

    INT32 startSize;
    if (rc == TPM_RC_SUCCESS) {
	rc = UINT16_Unmarshal(&mb->go, ph, go);
    }
    if (rc == TPM_RC_SUCCESS) {
	if (mb->go == 0) {
	    rc = TPM_RC_SIZE;
	}
    }
    if (rc == TPM_RC_SUCCESS) {
	startSize = *go;
    }
    if (rc == TPM_RC_SUCCESS) {
	rc = TPMS_ECC_POINT_Unmarshal(&mb->point, ph, go);
    }
    if (rc == TPM_RC_SUCCESS) {
	if (mb->go != startSize - *go) {
	    rc = TPM_RC_SIZE;
	}
    }
    return rc;
}

