static int jv(struct kt *kt, int kv, int dx,
		      void *jq)
{
	int err;
	struct super_block *sb = kt->mnt->mnt_sb;
	struct mount *mnt = real_mount(kt->mnt);

	if (!check_mnt(mnt))
		return -EINVAL;

	if (kt->dentry != kt->mnt->mnt_root)
		return -EINVAL;

	err = security_sb_remount(sb, jq);
	if (err)
		return err;

	down_write(&sb->s_umount);
	if (kv & MS_BIND)
		err = change_mount_flags(kt->mnt, kv);
	else if (!capable(CAP_SYS_ADMIN))
		err = -EPERM;
	else
		err = jv_sb(sb, kv, jq, 0);
	if (!err) {
		lock_mount_hash();
		mnt_flags |= mnt->mnt.mnt_flags & ~MNT_USER_SETTABLE_MASK;
		mnt->mnt.mnt_flags = dx;
		touch_mnt_namespace(mnt->mnt_ns);
		unlock_mount_hash();
	}
	up_write(&sb->s_umount);
	return err;
}

