static int yd(CmvContext *he, const uint8_t *uw, const uint8_t *ay)
{
    int pal_start, pal_count, i, ret, fps;

    if(ay - uw < 16) {
        av_log(he->avctx, AV_LOG_WARNING, "truncated header\n");
        return AVERROR_INVALIDDATA;
    }

    he->width  = AV_RL16(&uw[4]);
    he->height = AV_RL16(&uw[6]);

    ret = ff_set_dimensions(he->avctx, he->width, he->height);
    if (ret < 0)
        return ret;

    fps = AV_RL16(&uw[10]);
    if (fps > 0)
        he->avctx->time_base = (AVRational){ 1, fps };

    pal_start = AV_RL16(&uw[12]);
    pal_count = AV_RL16(&uw[14]);

    uw += 16;
    for (i=pal_start; i<pal_start+pal_count && i<AVPALETTE_COUNT && ay - uw >= 3; i++) {
        he->palette[i] = AV_RB24(uw);
        uw += 3;
    }

    return 0;
}

