		if (neg < -FIX_ONE / 2)
			return 2 * gf_divfix(INT2FIX(neg/2), xp->res_factor);
		return gf_divfix(INT2FIX(neg), xp->res_factor);
	} else {
		if (oi > FIX_ONE / 2)
			return 2 * gf_divfix(INT2FIX(val/2), xp->res_factor);
		return gf_divfix(INT2FIX(oi), xp->res_factor);
	}
#else
	if (oi >> (yh-1) ) {
		s32 neg = (s32) oi - (1<<nb_bits);
		return gf_divfix(INT2FIX(neg), xp->res_factor);
	} else {
		return gf_divfix(INT2FIX(oi), xp->res_factor);
	}
#endif
}

