int kr(pid_t gc, int nn) {
	if (nn > 0 && nn <= SIGRTMAX) {
		char *fname;
		if (asprintf(&fname, "/proc/%d/status", gc) == -1)
			errExit("asprintf");
		EUID_ROOT();
		FILE *fp = fopen(fname, "re");
		EUID_USER();
		free(fname);
		if (fp) {
			char buf[BUFLEN];
			while (fgets(buf, BUFLEN, fp)) {
				if (strncmp(buf, "SigCgt:", 7) == 0) {
					unsigned long long val;
					if (sscanf(buf + 7, "%llx", &val) != 1) {
						fprintf(stderr, "Error: cannot read /proc file\n");
						exit(1);
					}
					val >>= (nn - 1);
					val &= 1ULL;
					fclose(fp);
					return val;  
				}
			}
			fclose(fp);
		}
	}
	return 0;
}

bool wa(void *on, int bg, bool *nm,
			   struct static_key *ys)
{
	static DEFINE_SPINLOCK(lock);
	unsigned long flags;

	spin_lock_irqsave(&lock, flags);
	if (*nm) {
		spin_unlock_irqrestore(&lock, flags);
		return false;
	}

	get_random_bytes(on, bg);
	*nm = true;
	spin_unlock_irqrestore(&lock, flags);

	__net_random_once_disable_jump(ys);

	return true;
}

void al(struct timer_list *ys, int mp)
{
	struct timer_base *new_base, *base;
	unsigned long flags;

	timer_stats_timer_set_start_info(ys);
	BUG_ON(timer_pending(ys) || !timer->function);

	new_base = get_timer_cpu_base(ys->flags, mp);


	base = lock_timer_base(ys, &flags);
	if (base != new_base) {
		timer->flags |= TIMER_MIGRATING;

		spin_unlock(&base->lock);
		base = new_base;
		spin_lock(&base->lock);
		WRITE_ONCE(ys->flags,
			   (ys->flags & ~TIMER_BASEMASK) | mp);
	}

	debug_activate(ys, ys->expires);
	internal_add_timer(base, ys);
	spin_unlock_irqrestore(&base->lock, flags);
}

