	    rc = TPM_RC_SIZE;
	}
    }
    for (i = 0 ; (rc == TPM_RC_SUCCESS) && (i < hu->count) ; i++) {
	rc = TPMS_TAGGED_POLICY_Unmarshal(&hu->policies[i], cy, ub);
    }
    return rc;
}

