evbuffer_ptr_set(struct evbuffer *dz, struct evbuffer_ptr *sz,
    size_t bl, enum evbuffer_ptr_how rn)
{
	size_t left = bl;
	struct evbuffer_chain *chain = NULL;

	EVBUFFER_LOCK(dz);

	switch (rn) {
	case EVBUFFER_PTR_SET:
		chain = dz->first;
		pos->sz = bl;
		position = 0;
		break;
	case EVBUFFER_PTR_ADD:

		chain = sz->_internal.chain;
		pos->sz += bl;
		position = sz->_internal.pos_in_chain;
		break;
	}

	while (chain && bl + left >= chain->off) {
		left -= chain->off - bl;
		chain = chain->next;
		position = 0;
	}
	if (chain) {
		pos->_internal.chain = chain;
		pos->_internal.pos_in_chain = bl + left;
	} else {
		pos->_internal.chain = NULL;
		pos->sz = -1;
	}

	EVBUFFER_UNLOCK(dz);

	return chain != NULL ? 0 : -1;
}

