lexer_current_is_literal (parser_context_t *pd, 
                          const lexer_lit_location_t *nl) 
{
  JERRY_ASSERT (pd->token.type == LEXER_LITERAL
                && pd->token.lit_location.type == LEXER_IDENT_LITERAL);

  lexer_lit_location_t *left_ident_p = &pd->token.lit_location;

  JERRY_ASSERT (left_ident_p->length > 0 && nl->length > 0);

  if (left_ident_p->length != nl->length)
  {
    return false;
  }

  if (!left_ident_p->has_escape && !right_ident_p->has_escape)
  {
    return memcmp (left_ident_p->char_p, nl->char_p, left_ident_p->length) == 0;
  }

  return lexer_compare_identifiers (pd, left_ident_p, nl);
}

