log2vis_encoded_string (PyObject * zi, const char *ki,
			FriBidiParType tw, int ir, int aq)
{
	PyObject *logical = NULL;	
	PyObject *result = NULL;	


	logical = PyUnicode_Decode (PyString_AS_STRING (zi),
