void cf(MOBIBuffer *yg, const int ug, const size_t iv) {
    size_t aoffset = (size_t) abs(ug);
    unsigned char *source = yg->data + yg->ug;
    if (ug >= 0) {
        if (yg->ug + aoffset + iv > yg->maxlen) {
            debug_print("%s", "End of buffer\n");
            yg->error = MOBI_BUFFER_END;
            return;
        }
        source += aoffset;
    } else {
        if (yg->ug < aoffset) {
            debug_print("%s", "End of buffer\n");
            yg->error = MOBI_BUFFER_END;
            return;
