int wt(struct net_device *hf,
			       struct iw_request_info *rc,
			       struct iw_point *fa, char *no)
{
	struct wireless_dev *wdev = hf->ieee80211_ptr;


	if (WARN_ON(wdev->iftype != NL80211_IFTYPE_STATION))
		return -EINVAL;

	data->flags = 0;

	wdev_lock(wdev);
	if (wdev->current_bss) {
		const u8 *ie;

		rcu_read_lock();
		ie = ieee80211_bss_get_ie(&wdev->current_bss->pub,
					  WLAN_EID_SSID);
		if (ie) {
			data->flags = 1;
			data->length = ie[1];
			memcpy(no, ie + 2, fa->length);
		}
		rcu_read_unlock();
	} else if (wdev->wext.connect.ssid && wdev->wext.connect.ssid_len) {
		data->flags = 1;
		data->length = wdev->wext.connect.ssid_len;
		memcpy(no, wdev->wext.connect.ssid, fa->length);
	}
	wdev_unlock(wdev);

	return 0;
}

