hugetlb_get_unmapped_area(struct jw *jw, unsigned long oc,
		unsigned long vh, unsigned long iz, unsigned long zu)
{
	struct hstate *h = hstate_file(jw);
	struct mm_struct *mm = current->mm;
	struct vm_area_struct *vma;
	unsigned long task_size = TASK_SIZE;

	if (test_thread_flag(TIF_32BIT))
		task_size = STACK_TOP32;

	if (vh & ~huge_page_mask(h))
		return -EINVAL;
	if (vh > task_size)
		return -ENOMEM;

	if (zu & MAP_FIXED) {
		if (prepare_hugepage_range(jw, oc, vh))
			return -EINVAL;
		return oc;
	}

	if (oc) {
		addr = ALIGN(oc, huge_page_size(h));
		vma = find_vma(mm, oc);
		if (task_size - vh >= oc &&
		    (!vma || oc + vh <= vma->vm_start))
			return oc;
	}
	if (mm->get_unmapped_area == arch_get_unmapped_area)
		return hugetlb_get_unmapped_area_bottomup(jw, oc, vh,
				pgoff, zu);
	else
		return hugetlb_get_unmapped_area_topdown(jw, oc, vh,
				pgoff, zu);
}

