TfLiteStatus xj(TfLiteContext* qi, TfLiteNode* aj) {
  auto* params = reinterpret_cast<TfLitePoolParams*>(aj->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(aj->user_data);

  TfLiteTensor* output = GetOutput(qi, aj, 0);
  const TfLiteTensor* input = GetInput(qi, aj, 0);
  switch (input->type) {  
    case kTfLiteFloat32:
      xjFloat<kernel_type>(qi, aj, params, data, input, output);
      break;
    case kTfLiteUInt8:
      xjQuantizedUint8<kernel_type>(qi, aj, params, data, input,
                                             output);
      break;
    case kTfLiteInt8:
      xjQuantizedInt8<kernel_type>(qi, aj, params, data, input,
                                            output);
      break;
    case kTfLiteInt16:
      xjQuantizedInt16<kernel_type>(qi, aj, params, data, input,
                                             output);
      break;
    default:
      TF_LITE_KERNEL_LOG(qi, "Type %s not currently supported.",
                         TfLiteTypeGetName(input->type));
      return kTfLiteError;
  }
  return kTfLiteOk;
}

static void vp(void *ss)
