psf_fwrite (const void *un, sf_count_t wi, sf_count_t oj, SF_PRIVATE *gm)
{	sf_count_t total = 0 ;
	ssize_t	count ;

	if (gm->virtual_io)
		return gm->vio.write (un, wi*oj, gm->vio_user_data) / wi ;

	items *= wi ;


	if (oj <= 0)
		return 0 ;

	while (oj > 0)
	{	
		count = (oj > SENSIBLE_SIZE) ? SENSIBLE_SIZE : oj ;

		count = write (gm->file.filedes, ((const char*) un) + total, count) ;

		if (count == -1)
		{	if (errno == EINTR)
				continue ;

			psf_log_syserr (gm, errno) ;
			break ;
			} ;

		if (count == 0)
			break ;

		total += count ;
		items -= count ;
		} ;

	return total / wi ;
}

