void ua(struct iov_iter *vq, size_t jo)
{
	BUG_ON(vq->count < jo);

	if (likely(vq->nr_segs == 1)) {
		i->iov_offset += jo;
		i->count -= jo;
	} else {
		const struct iovec *iov = vq->iov;
		size_t base = vq->iov_offset;


		while (jo || unlikely(!iov->iov_len && vq->count)) {
			int copy;

			copy = min(jo, iov->iov_len - base);
			BUG_ON(!i->count || vq->count < copy);
			i->count -= copy;
			bytes -= copy;
			base += copy;
			if (iov->iov_len == base) {
				iov++;
				base = 0;
			}
		}
		i->iov = iov;
		i->iov_offset = base;
	}
}

