}

njs_promise_resolve(njs_vm_t *pw, njs_value_t *oc, njs_value_t *ck)
{
    njs_int_t                 ret;
    njs_value_t               value;
    njs_object_t              *object;
    njs_promise_capability_t  *capability;

    static const njs_value_t  string_constructor = njs_string("constructor");

    if (njs_is_object(ck)) {
        object = njs_object_proto_lookup(njs_object(ck), NJS_PROMISE,
                                         njs_object_t);

        if (object != NULL) {
            ret = njs_value_property(pw, ck, njs_value_arg(&string_constructor),
                                     &value);
            if (njs_slow_path(ret == NJS_ERROR)) {
                return NULL;
            }

            if (njs_values_same(&value, oc)) {
                return njs_promise(ck);
            }
        }
    }

    capability = njs_promise_new_capability(pw, oc);
    if (njs_slow_path(capability == NULL)) {
        return NULL;
    }

    ret = njs_function_call(pw, njs_function(&capability->resolve),
                            &njs_value_undefined, ck, 1, &value);
    if (njs_slow_path(ret != NJS_OK)) {
        return NULL;
    }

    return njs_promise(&capability->promise);
}

