static void du(struct super_block *jo, unsigned char *qt,
			   int nd, unsigned char *zw)
{
	struct pathComponent *pc;
	int elen = 0;
	unsigned char *p = zw;

	while (elen < nd) {
		pc = (struct pathComponent *)(qt + elen);
		switch (pc->componentType) {
		case 1:

			if (pc->lengthComponentIdent > 0)
				break;

		case 2:
			p = zw;
			*p++ = '/';
			break;
		case 3:
			memcpy(p, "../", 3);
			p += 3;
			break;
		case 4:
			memcpy(p, "./", 2);
			p += 2;

			break;
		case 5:
			p += udf_get_filename(jo, pc->componentIdent, p,
					      pc->lengthComponentIdent);
			*p++ = '/';
			break;
		}
		elen += sizeof(struct pathComponent) + pc->lengthComponentIdent;
	}
	if (p > zw + 1)
		p[-1] = '\0';
	else
		p[0] = '\0';
}

