le64addr_string(netdissect_options *cc, const u_char *nd)
{
	const unsigned int len = 8;
	register u_int i;
	register char *cp;
	register struct enamemem *tp;
	char buf[BUFSIZE];

	tp = lookup_bytestring(cc, nd, len);
	if (tp->e_name)
		return (tp->e_name);

	cp = buf;
	for (i = len; i > 0 ; --i) {
		*cp++ = hex[*(nd + i - 1) >> 4];
		*cp++ = hex[*(nd + i - 1) & 0xf];
		*cp++ = ':';
	}
	cp --;

	*cp = '\0';

	tp->e_name = strdup(buf);
	if (tp->e_name == NULL)
		(*cc->ndo_error)(cc, "le64addr_string: strdup(buf)");

	return (tp->e_name);
}

