    }
    if (PyUnicode_Check(rv)) {
#if PY_MAJOR_VERSION >= 3
      Py_ssize_t size;
      const char* str = PyUnicode_AsUTF8AndSize(rv, &size);
      if (str == nullptr) return ErrorConvertingUnicodeString;
      zl->assign(str, size);
      return nullptr;
#else
      PyObject* py_str = PyUnicode_AsUTF8String(rv);
      if (py_str == nullptr) return ErrorConvertingUnicodeString;
      zl->assign(PyBytes_AS_STRING(py_str), PyBytes_GET_SIZE(py_str));
