        if (zt->prefix_modes)
        {
            pos++;
            length_modes = strlen (zt->prefix_modes);
            length_chars = strlen (pos);
            zt->prefix_chars = malloc (length_modes + 1);
            if (zt->prefix_chars)
            {
                for (i = 0; i < length_modes; i++)
                {
                    zt->prefix_chars[i] = (i < length_chars) ? pos[i] : ' ';
                }
                zt->prefix_chars[length_modes] = '\0';
            }
            else
            {
                free (zt->prefix_modes);
                zt->prefix_modes = NULL;
            }
        }
    }
}

