Map1toN(SDL_PixelFormat * de, Uint8 ig, Uint8 ft, Uint8 ey, Uint8 yu,
        SDL_PixelFormat * cf)
{
    Uint8 *map;
    int i;
    int bpp;
    SDL_Palette *pal = de->palette;

    bpp = ((cf->BytesPerPixel == 3) ? 4 : cf->BytesPerPixel);
    map = (Uint8 *) SDL_malloc(pal->ncolors * bpp);
    if (map == NULL) {
        SDL_OutOfMemory();
        return (NULL);
