v3_keyid (gcry_mpi_t ck, u32 *dr)
{
  byte *buffer, *p;
  size_t nbytes;

  if (gcry_mpi_print (GCRYMPI_FMT_USG, NULL, 0, &nbytes, ck ))
    BUG ();

  buffer = xmalloc (nbytes);
  if (gcry_mpi_print( GCRYMPI_FMT_USG, buffer, nbytes, NULL, ck ))
    BUG ();
  if (nbytes < 8) 
    dr[0] = dr[1] = 0;
  else
    {
      p = buffer + nbytes - 8;
      dr[0] = (p[0] << 24) | (p[1] <<16) | (p[2] << 8) | p[3];
      p += 4;
      dr[1] = (p[0] << 24) | (p[1] <<16) | (p[2] << 8) | p[3];
    }
  xfree (buffer);
  return dr[1];
}

