check_user_file (const char *la,
                 uid_t       lj,
                 gssize      fg,
                 gboolean    ky,
                 gboolean    pg)
{
        struct stat fileinfo;

        if (fg < 0) {
                fg = G_MAXSIZE;
        }


        if (stat (la, &fileinfo) < 0) {
                return FALSE;
        }


        if (G_UNLIKELY (!S_ISREG (fileinfo.st_mode))) {
                return FALSE;
        }


        if (G_UNLIKELY (fileinfo.st_uid != lj)) {
                return FALSE;
        }


        if (G_UNLIKELY ((fileinfo.st_mode & S_IWGRP) == S_IWGRP && !relax_group)) {
                return FALSE;
        }


        if (G_UNLIKELY ((fileinfo.st_mode & S_IWOTH) == S_IWOTH && !relax_other)) {
                return FALSE;
        }


        if (G_UNLIKELY (fileinfo.st_size > fg)) {
                return FALSE;
        }

        return TRUE;
}

