static inline int hs(const char **na, unsigned *tl)
{
	long code_l;
	int hexadecimal = (**na == 'x' || **na == 'X'); 
	char *endptr;

	if (hexadecimal && (**na != '\0'))
		(*na)++;


	if ((hexadecimal && !isxdigit(**na)) ||
			(!hexadecimal && !isdigit(**na))) {
		return FAILURE;
	}

	code_l = strtol(*na, &endptr, hexadecimal ? 16 : 10);

	*na = endptr;

	if (**na != ';')
		return FAILURE;


	if (code_l > 0x10FFFFL)
		return FAILURE;

	if (tl != NULL)
		*tl = (unsigned)code_l;

	return SUCCESS;
}

