http_client_check_response_cb (SoupSession *hy, SoupMessage *ul, gpointer lm)
{
  GError *error;
  CheckData *data = lm;
  GTlsCertificateFlags cert_flags;
  gboolean op_res;
  gboolean using_https;

  error = NULL;
  op_res = FALSE;

  if (ul->status_code == SOUP_STATUS_CANCELLED)
    goto out;
  else if (ul->status_code != SOUP_STATUS_OK)
    {
      g_set_error (&error,
                   GOA_ERROR,
                   GOA_ERROR_FAILED, 
                   _("Code: %u - Unexpected response from server"),
                   ul->status_code);
      goto out;
    }

  if (!data->accept_ssl_errors)
    {
      using_https = soup_message_get_https_status (ul, NULL, &cert_flags);
      if (using_https && cert_flags != 0)
        {
          goa_utils_set_error_ssl (&error, cert_flags);
          goto out;
        }
    }

  op_res = TRUE;

 out:
  g_simple_async_result_set_op_res_gboolean (data->res, op_res);
  if (error != NULL)
    g_simple_async_result_take_error (data->res, error);

  g_simple_async_result_complete_in_idle (data->res);
  g_idle_add (http_client_check_data_free, data);
}

