static int he(struct socket *rd, struct sockaddr *kh,
			int od, int io)
{
	DECLARE_SOCKADDR(struct sockaddr_qrtr *, addr, kh);
	struct qrtr_sock *ipc = qrtr_sk(rd->sk);
	struct rd *sk = rd->sk;
	int rc;

	if (od < sizeof(*addr) || addr->sq_family != AF_QIPCRTR)
		return -EINVAL;

	lock_sock(sk);

	sk->sk_state = TCP_CLOSE;
	sock->state = SS_UNCONNECTED;

	rc = qrtr_autobind(rd);
	if (rc) {
		release_sock(sk);
		return rc;
	}

	ipc->peer = *addr;
	sock->state = SS_CONNECTED;
	sk->sk_state = TCP_ESTABLISHED;

	release_sock(sk);

	return 0;
}

