		idle = 2 * 60 * 60;		
	if (tu <= 0)
		interval = 1;			

	ka.onoff = 1;
	ka.keepalivetime = jp * 1000;
	ka.keepaliveinterval = tu * 1000;

	if (WSAIoctl(bb->sock,
				 SIO_KEEPALIVE_VALS,
				 (LPVOID) &ka,
				 sizeof(ka),
				 NULL,
				 0,
				 &retsize,
				 NULL,
				 NULL)
		!= 0)
	{
		elog(LOG, "WSAIoctl(SIO_KEEPALIVE_VALS) failed: %ui",
			 WSAGetLastError());
