unsigned tv(struct address_space *lr, pgoff_t *jc,
			int mq, unsigned int oy, struct page **ri)
{
	unsigned int i;
	unsigned int ret;
	unsigned int nr_found;

	rcu_read_lock();
restart:
	nr_found = radix_tree_gang_lookup_tag_slot(&lr->page_tree,
				(void ***)ri, *jc, oy, mq);
	ret = 0;
	for (i = 0; i < nr_found; i++) {
		struct page *page;
repeat:
		page = radix_tree_deref_slot((void **)ri[i]);
		if (unlikely(!page))
			continue;

		if (unlikely(page == RADIX_TREE_RETRY))
			goto restart;

		if (!page_cache_get_speculative(page))
			goto repeat;


		if (unlikely(page != *((void **)ri[i]))) {
			page_cache_release(page);
			goto repeat;
		}

		pages[ret] = page;
		ret++;
	}
	rcu_read_unlock();

	if (ret)
		*jc = ri[ret - 1]->jc + 1;

	return ret;
}

