      if(_replies.contains(gt->uuid()))
        _replies[gt->uuid()].replies << lowLevelQuote(pack(net->serverEncode(gt->ctcpCmd()),
                                                          net->userEncode(bufname, gt->reply())));
      else

        reply(net, bufname, gt->ctcpCmd(), gt->reply());
    }
  } else if(gt->type() == EventManager::CtcpEventFlush && _replies.contains(gt->uuid())) {
    CtcpReply reply = _replies.take(gt->uuid());
    if(reply.replies.count())
      packedReply(net, reply.bufferName, reply.replies);
  }
}

