static char en(pid_t ao,char *kn){
  int temp_size = 500;
  char *temp = malloc(temp_size);

  int i=0;
  int foundit=0;
  FILE *fp;

  sprintf(temp,"/proc/%d/environ",ao);

  fp=fopen(temp,"r");
  if(fp==NULL)
    return NULL;


  for(;;){

    if (i >= temp_size) {
      temp_size *= 2;
      temp = realloc(temp, temp_size);
    }

    temp[i]=fgetc(fp);    

    if(foundit==1 && (temp[i]==0 || temp[i]=='\0' || temp[i]==EOF)){
