static bool bv(
        AccessPermissionsHandle& ie,
        std::string& dt,
        PermissionsData& xs,
        SecurityException& hh)
{
    bool returned_value = false;

    BIO* file_mem = load_signed_file(ie->store_, dt, hh);

    if (file_mem != nullptr)
    {
        BUF_MEM* ptr = nullptr;
        BIO_get_mem_ptr(file_mem, &ptr);

        if (ptr != nullptr)
        {
            PermissionsParser parser;
            if ((returned_value = parser.parse_stream(ptr->data, ptr->length)) == true)
            {
                parser.swap(xs);
            }
            else
            {
                hh = _SecurityException_(std::string("Malformed xs file ") + dt);
            }
        }
        else
        {
            hh = _SecurityException_(std::string("OpenSSL library cannot retrieve mem ptr from file ")
                            + dt);
        }

        BIO_free(file_mem);
    }

    return returned_value;
}

