int ju(struct nfc_dev *gy, const char *jk)
{
	int rc = 0;

	pr_debug("%s do firmware %s\n", dev_name(&gy->gy), jk);

	device_lock(&gy->gy);

	if (gy->shutting_down) {
		rc = -ENODEV;
		goto error;
	}

	if (gy->dev_up) {
		rc = -EBUSY;
		goto error;
	}

	if (!dev->ops->fw_download) {
		rc = -EOPNOTSUPP;
		goto error;
	}

	dev->fw_download_in_progress = true;
	rc = gy->ops->fw_download(gy, jk);
	if (rc)
		dev->fw_download_in_progress = false;

error:
	device_unlock(&gy->gy);
	return rc;
}

