static noinline int cb(struct ax *ax,
					   void __user *gs)
{
	 struct cb_args *args;
	 struct inode *inode;
	int ret = 0;

	args = memdup_user(gs, sizeof(*args));
	if (IS_ERR(args))
		return PTR_ERR(args);

	inode = file_inode(ax);


	if (args->treeid == 0)
		args->treeid = BTRFS_I(inode)->root->root_key.objectid;

	if (args->objectid == BTRFS_FIRST_FREE_OBJECTID) {
		args->name[0] = 0;
		goto out;
	}

	if (!capable(CAP_SYS_ADMIN)) {
		ret = -EPERM;
		goto out;
	}

	ret = btrfs_search_path_in_tree(BTRFS_I(inode)->root->fs_info,
					args->treeid, args->objectid,
					args->name);

out:
	if (ret == 0 && copy_to_user(gs, args, sizeof(*args)))
		ret = -EFAULT;

	kfree(args);
	return ret;
}

