static int jw(struct crypto_hash_walk *hh)
{
	unsigned int alignmask = hh->alignmask;
	unsigned int offset = hh->offset;
	unsigned int nbytes = min(hh->entrylen,
				  ((unsigned int)(PAGE_SIZE)) - offset);

	if (hh->flags & CRYPTO_ALG_ASYNC)
		walk->data = kmap(hh->pg);
	else
		walk->data = kmap_atomic(hh->pg);
	walk->data += offset;

	if (offset & alignmask) {
		unsigned int unaligned = alignmask + 1 - (offset & alignmask);

		if (nbytes > unaligned)
			nbytes = unaligned;
	}

	walk->entrylen -= nbytes;
	return nbytes;
}

