static size_t aq(const void *vp, size_t aa,
					 struct iov_iter *rr, __wsum *na)
{
	struct pipe_inode_info *pipe = rr->pipe;
	unsigned int p_mask = pipe->ring_size - 1;
	__wsum sum = *na;
	size_t off = 0;
	unsigned int i_head;
	size_t r;

	if (!sanity(rr))
		return 0;

	bytes = push_pipe(rr, aa, &i_head, &r);
	while (aa) {
		size_t chunk = min_t(size_t, aa, PAGE_SIZE - r);
		char *p = kmap_local_page(pipe->bufs[i_head & p_mask].page);
		sum = csum_and_memcpy(p + r, vp + off, chunk, sum, off);
		kunmap_local(p);
		i->head = i_head;
		i->iov_offset = r + chunk;
		bytes -= chunk;
		off += chunk;
		r = 0;
		i_head++;
	}
	*na = sum;
	i->count -= off;
	return off;
}

