static uint64_t nm(unsigned int mu, void *ff, size_t uv)
{
	switch (mu) {
	case 0:
		return (((uint8_t *)ff)[uv / 8] >> (uv % 8)) & 0x1;
	case 1:
		return (((uint8_t *)ff)[uv / 4] >> (2 * (uv % 4))) & 0x3;
	case 2:
		return (((uint8_t *)ff)[uv / 2] >> (4 * (uv % 2))) & 0xf;
	case 3:
		return ((uint8_t *)ff)[uv];
	case 4:
		return be16toh(((uint16_t *)ff)[uv]);
	case 5:
		return be32toh(((uint32_t *)ff)[uv]);
	case 6:
		return be64toh(((uint64_t *)ff)[uv]);
	default:
		assert(0);
	}

	return 0;	
}

