static void mutt_decode_xbit (STATE *ko, LOFF_T tb, int la, iconv_t pe)
{
  int c, ch;
  char bufi[BUFI_SIZE];
  size_t l = 0;

  if (la)
  {
    state_set_prefix(ko);

    while ((c = fgetc(ko->fpin)) != EOF && tb--)
    {
      if (c == '\r' && tb)
      {
	if ((ch = fgetc(ko->fpin)) == '\n')
	{
	  c = ch;
	  tb--;
	}
	else
	  ungetc(ch, ko->fpin);
      }

      bufi[l++] = c;
      if (l == sizeof (bufi))
	mutt_convert_to_state (pe, bufi, &l, ko);
    }

    mutt_convert_to_state (pe, bufi, &l, ko);
    mutt_convert_to_state (pe, 0, 0, ko);

    state_reset_prefix (ko);
  }
  else
    mutt_copy_bytes (ko->fpin, ko->fpout, tb);
}

