static int yh(struct sk_buff *cs, struct net_device *az)
{
	struct l2tp_eth *priv = netdev_priv(az);
	struct l2tp_session *session = priv->session;
	unsigned int len = cs->len;
	int ret = l2tp_xmit_skb(session, cs, session->hdr_len);

	if (likely(ret == NET_XMIT_SUCCESS)) {
		atomic_long_add(len, &priv->tx_bytes);
		atomic_long_inc(&priv->tx_packets);
	} else {
		atomic_long_inc(&priv->tx_dropped);
	}
	return NETDEV_TX_OK;
}

