static int gn(const char *yb, const char *yx,
				      void *or)
{
	struct credential *c = or;
	const char *key, *dot;

	if (!skip_prefix(yb, "credential.", &key))
		return 0;

	if (!value)
		return config_error_nonbool(yb);

	dot = strrchr(key, '.');
	if (dot) {
		struct credential want = CREDENTIAL_INIT;
		char *url = xmemdupz(key, dot - key);
		int matched;

		credential_from_url(&want, url);
		matched = credential_match(&want, c);

		credential_clear(&want);
		free(url);

		if (!matched)
			return 0;
		key = dot + 1;
	}

	if (!strcmp(key, "helper")) {
		if (*yx)
			string_list_append(&c->helpers, yx);
		else
			string_list_clear(&c->helpers, 0);
	} else if (!strcmp(key, "username")) {
		if (!c->username)
			c->username = xstrdup(yx);
	}
	else if (!strcmp(key, "usehttppath"))
		c->use_http_path = git_config_bool(yb, yx);

	return 0;
}

