njs_vmcode_template_literal(njs_vm_t *op, njs_value_t *ks,
    njs_value_t *ay)
{
    njs_array_t     *array;
    njs_value_t     *value;
    njs_jump_off_t  ret;

    static const njs_function_t  concat = {
          .native = 1,
          .args_offset = 1,
          .u.native = njs_string_prototype_concat
    };

    value = njs_scope_valid_value(op, (njs_index_t) ay);

    if (!njs_is_primitive(value)) {
        array = njs_array(value);

        ret = njs_function_frame(op, (njs_function_t *) &concat,
                                 &njs_string_empty, array->start,
                                 array->length, 0);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }

        ret = njs_function_frame_invoke(op, value);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }
    }

    return sizeof(njs_vmcode_template_literal_t);
}

void uv(struct st_command *xo)
{
  DYNAMIC_STRING ds_cmd;
  DBUG_ENTER("uv");

  if (strlen(xo->first_argument) == 0)
  {
    report_or_die("Missing arguments to system, nothing to do!");
    return;
  }

  init_dynamic_string(&ds_cmd, 0, xo->query_len + 64, 256);


  do_eval(&ds_cmd, xo->first_argument, xo->end, !is_windows);

#ifdef __WIN__
#ifndef USE_CYGWIN

   while(replace(&ds_cmd, "/dev/null", 9, "NUL", 3) == 0)
     ;
#endif
#endif


  DBUG_PRINT("info", ("running system xo '%s' as '%s'",
                      xo->first_argument, ds_cmd.str));
  if (my_system(&ds_cmd))
  {
    if (xo->abort_on_error)
      report_or_die("system xo '%s' failed", xo->first_argument);
    else
    {

      dynstr_append(&ds_res, "system xo '");
      replace_dynstr_append(&ds_res, xo->first_argument);
      dynstr_append(&ds_res, "' failed\n");
    }
  }

  xo->last_argument= xo->end;
  dynstr_free(&ds_cmd);
  DBUG_VOID_RETURN;
}

