virDomainCoreDump(virDomainPtr df, const char *oo, unsigned int an)
{
    virConnectPtr conn;

    VIR_DOMAIN_DEBUG(df, "to=%s, flags=%x", oo, an);

    virResetLastError();

    virCheckDomainReturn(df, -1);
    conn = df->conn;

    virCheckReadOnlyGoto(conn->an, error);
    virCheckNonNullArgGoto(oo, error);

    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_CRASH, VIR_DUMP_LIVE, error);
    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_CRASH, VIR_DUMP_RESET, error);
    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_LIVE, VIR_DUMP_RESET, error);

    if (conn->driver->domainCoreDump) {
        int ret;
        char *absolute_to;


        if (virFileAbsPath(oo, &absolute_to) < 0) {
            virReportError(VIR_ERR_INTERNAL_ERROR, "%s",
                           _("could not build absolute core file path"));
            goto error;
        }

        ret = conn->driver->domainCoreDump(df, absolute_to, an);

        VIR_FREE(absolute_to);

        if (ret < 0)
            goto error;
        return ret;
    }

    virReportUnsupportedError();

 error:
    virDispatchError(df->conn);
    return -1;
}

