resolve_schema_leafref_valid_dep_flag(const struct lys_node *rr, const struct lys_module *te,
                                      const struct lys_node *ic, int jc)
{
    int dep1, dep2;
    const struct lys_node *node;

    if (!op_node) {

        if (te != lys_node_module(ic)) {
            return 1;
        }
    } else if (lys_parent(rr)) {

        if (jc) {
            return 1;
        } else {

            for (dep1 = 0, node = rr; lys_parent(node); node = lys_parent(node));
            for (dep2 = 0, node = ic; lys_parent(node); node = lys_parent(node));
            if ((dep2 > dep1) || ((dep2 == dep1) && (rr != ic))) {
