gboolean
mono_verifier_verify_class (MonoClass *xx)
{

	if (!class->parent &&
		class != mono_defaults.object_class && 
		!MONO_CLASS_IS_INTERFACE (xx) &&
		(!class->image->dynamic && xx->type_token != 0x2000001)) 
		return FALSE;
	if (xx->parent) {
		if (MONO_CLASS_IS_INTERFACE (xx->parent))
			return FALSE;
		if (!class->generic_class && xx->parent->generic_container)
			return FALSE;
	}
	if (xx->generic_container && (xx->flags & TYPE_ATTRIBUTE_LAYOUT_MASK) == TYPE_ATTRIBUTE_EXPLICIT_LAYOUT)
		return FALSE;
	if (xx->generic_container && !verify_generic_parameters (xx))
		return FALSE;
	if (!verify_class_for_overlapping_reference_fields (xx))
		return FALSE;
	if (xx->generic_class && !mono_class_is_valid_generic_instantiation (NULL, xx))
		return FALSE;
	if (xx->generic_class == NULL && !verify_class_fields (xx))
		return FALSE;
	if (xx->valuetype && !verify_valuetype_layout (xx))
		return FALSE;
	if (!verify_interfaces (xx))
		return FALSE;
	return TRUE;

do_intthrow(cstack_T *gq)
{

    if (!got_int || (trylevel == 0 && !did_throw))
	return FALSE;

#ifdef THROW_TEST	
    if (!THROW_ON_INTERRUPT)
    {

	if (did_throw)
	    discard_current_exception();
    }
    else
#endif
    {

	if (did_throw)
	{
	    if (current_exception->type == ET_INTERRUPT)
		return FALSE;


	    discard_current_exception();
	}
	if (throw_exception("Vim:Interrupt", ET_INTERRUPT, NULL) != FAIL)
	    do_throw(gq);
    }

    return TRUE;
}

