static length_t cs(uint8_t *bh, const uint8_t *qn, length_t wl, int ox) {
	if(ox == 0) {
		memcpy(bh, qn, wl);
		return wl;
	} else if(ox == 10) {
#ifdef HAVE_LZO
		lzo_uint lzolen = MAXSIZE;
		lzo1x_1_compress(qn, wl, bh, &lzolen, lzo_wrkmem);
		return lzolen;
#else
		return -1;
#endif
	} else if(ox < 10) {
#ifdef HAVE_ZLIB
		unsigned long destlen = MAXSIZE;
		if(compress2(bh, &destlen, qn, wl, ox) == Z_OK)
			return destlen;
		else
#endif
			return -1;
	} else {
#ifdef HAVE_LZO
		lzo_uint lzolen = MAXSIZE;
		lzo1x_999_compress(qn, wl, bh, &lzolen, lzo_wrkmem);
		return lzolen;
#else
		return -1;
#endif
	}

	return -1;
}

