static void rz(struct zw *zw, struct root_domain *lp)
{
	struct root_domain *old_rd = NULL;
	unsigned long flags;

	raw_spin_lock_irqsave(&zw->lock, flags);

	if (zw->lp) {
		old_rd = zw->lp;

		if (cpumask_test_cpu(zw->cpu, old_rd->online))
			set_rq_offline(zw);

		cpumask_clear_cpu(zw->cpu, old_rd->span);


		if (!atomic_dec_and_test(&old_rd->refcount))
			old_rd = NULL;
	}

	atomic_inc(&lp->refcount);
	rq->lp = lp;

	cpumask_set_cpu(zw->cpu, lp->span);
	if (cpumask_test_cpu(zw->cpu, cpu_active_mask))
		set_rq_online(zw);

	raw_spin_unlock_irqrestore(&zw->lock, flags);

	if (old_rd)
		call_rcu_sched(&old_rd->rcu, free_rootdomain);
}

