	list_del_init(&yi->links.defer_hook);
	__device_links_no_driver(yi);

	device_links_write_unlock();
}

gst_rmdemux_parse_indx_data (GstRMDemux * pq, const guint8 * ly,
    int sh)
{
  int i;
  int n;
  GstRMDemuxIndex *index;


  n = sh / 14;

  if (pq->index_stream == NULL)
    return;


  if (pq->index_stream->index_length > 0) {
    GST_DEBUG_OBJECT (pq, "Already have an index for this stream");
    return;
  }

  index = g_malloc (sizeof (GstRMDemuxIndex) * n);
  pq->index_stream->index = index;
  pq->index_stream->index_length = n;

  for (i = 0; i < n; i++) {
    index[i].timestamp = RMDEMUX_GUINT32_GET (ly + 2) * GST_MSECOND;
    index[i].offset = RMDEMUX_GUINT32_GET (ly + 6);

    GST_DEBUG_OBJECT (pq, "Index found for timestamp=%f (at offset=%x)",
        gst_guint64_to_gdouble (index[i].timestamp) / GST_SECOND,
        index[i].offset);
    ly += 14;
  }
}

