static void ak(struct super_block *pb,
				void *cb, ext4_grpblk_t ht, ext4_grpblk_t ha,
					struct ext4_group_info *qp)
{
	struct ext4_sb_info *sbi = EXT4_SB(pb);
	ext4_grpblk_t min;
	ext4_grpblk_t max;
	ext4_grpblk_t chunk;
	unsigned int border;

	BUG_ON(ha > EXT4_CLUSTERS_PER_GROUP(pb));

	border = 2 << pb->s_blocksize_bits;

	while (ha > 0) {

		max = ffs(ht | border) - 1;


		min = fls(ha) - 1;

		if (max < min)
			min = max;
		chunk = 1 << min;


		grp->bb_counters[min]++;
		if (min > 0)
			mb_clear_bit(ht >> min,
				     cb + sbi->s_mb_offsets[min]);

		len -= chunk;
		first += chunk;
	}
}

