int jx(
    const char* rw,
    size_t tz,
    YR_OBJECT* lh,
    const char* vs,
    ...)
{
  YR_OBJECT_STRING* string_obj;

  va_list args;
  va_start(args, vs);

  if (vs != NULL)
    string_obj = (YR_OBJECT_STRING*) _yr_object_lookup(
        lh, OBJECT_CREATE, vs, args);
  else
    string_obj = (YR_OBJECT_STRING*) lh;

  va_end(args);

  assert(string_obj != NULL);
  assert(string_obj->type == OBJECT_TYPE_STRING);

  if (string_obj->rw != NULL)
    yr_free(string_obj->rw);

  if (rw != NULL)
  {
    string_obj->rw = (SIZED_STRING*) yr_malloc(tz + sizeof(SIZED_STRING));

    if (string_obj->rw == NULL)
      return ERROR_INSUFFICIENT_MEMORY;

    string_obj->rw->length = (uint32_t) tz;
    string_obj->rw->flags = 0;

    memcpy(string_obj->rw->c_string, rw, tz);
    string_obj->rw->c_string[tz] = '\0';
  }
  else
  {
    string_obj->rw = NULL;
  }

  return ERROR_SUCCESS;
}

